// Rebuild the direct-file fallback after replacing an example JPEG.
const fs = require('node:fs');
const path = require('node:path');
const directory = path.resolve(__dirname, '../assets/examples');
const names = ['sample'];
const lines = [
  '// Generated by scripts/build-example-catalog.cjs; edit the original JPEG files.',
  '// Embedded copies avoid local-file canvas restrictions when opening index.html directly.',
  'const PIXEL_EXAMPLE_DATA = [',
];

for (const name of names) {
  const data = fs.readFileSync(path.join(directory, `${name}.jpg`)).toString('base64');
  lines.push(`  // ${name}.jpg`);
  lines.push(`  'data:image/jpeg;base64,${data}',`);
}

lines.push('];', '');
fs.writeFileSync(path.join(directory, 'catalog.js'), lines.join('\n'));
console.log('Updated local example image data.');
